function w({registerIndicator:k,sourceValues:v,nulls:F}){k({id:"oa-dosc",name:"Derivative Oscillator (DOSC)",category:"Oscillators",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"rsiPeriod",type:"number",label:"RSI Period",default:14,min:1,max:500,step:1},{key:"ema1Period",type:"number",label:"EMA1 Period",default:5,min:1,max:500,step:1,tooltip:"First EMA smoothing of RSI"},{key:"ema2Period",type:"number",label:"EMA2 Period",default:3,min:1,max:500,step:1,tooltip:"Second EMA smoothing (double smooth)"},{key:"sigPeriod",type:"number",label:"Signal Period",default:9,min:1,max:500,step:1,tooltip:"SMA signal line period"}],plots:[{key:"dosc",type:"line",title:"DOSC",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",lineStyle:"dotted"}],calc(u,t){const p=Math.max(1,Math.floor(Number(t.rsiPeriod)||14)),D=Math.max(1,Math.floor(Number(t.ema1Period)||5)),E=Math.max(1,Math.floor(Number(t.ema2Period)||3)),b=Math.max(1,Math.floor(Number(t.sigPeriod)||9)),c=v(u,t.source??"close"),f=u.length,h=new Array(f).fill(NaN),l=1/p,y=2/(D+1),N=2/(E+1);let r=0,i=0,a=NaN,o=NaN;const P=new Array(b).fill(NaN);let s=0,m=0,n=0;for(let e=0;e<f;e++){const d=c[e];if(!Number.isFinite(d))continue;const M=e>0&&Number.isFinite(c[e-1])?c[e-1]:0,g=Math.max(d-M,0),x=Math.max(M-d,0);e<p?(r=g,i=x):(r=r*(1-l)+g*l,i=i*(1-l)+x*l);const S=i===0?100:100-100/(1+r/i);a=Number.isFinite(a)?a*(1-y)+S*y:S,o=Number.isFinite(o)?o*(1-N)+a*N:a;const A=P[s];Number.isFinite(A)?(n-=A,n+=o):(m+=1,n+=o),P[s]=o,s=(s+1)%b;const O=m>0?n/m:0;h[e]=o-O}return{dosc:F(h)}}})}export{w as default};
